import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`restaurant-delivery-ads`,heroTitle:`Launch delivery ads that drive orders`,heroSubtitle:`Perplexity Computer analyzes your restaurant, builds high-converting delivery ads, and optimizes them across platforms — automatically.`,inputUrlCta:`Build my delivery ads`,inputUrlPlaceholder:`yourrestaurant.com`,inputUrlPrefill:`Go to {url} and perform a deep analysis of this restaurant — extract the brand name, cuisine type, menu highlights, delivery platforms (UberEats, DoorDash, Grubhub, etc.), price positioning, location, and visual style. Then build me a complete delivery ad campaign. 1) Create ad copy variations for each major delivery platform — headlines, descriptions, and CTAs optimized for delivery conversions. 2) Build Google Ads search campaigns targeting local delivery keywords like '[cuisine] delivery near me', '[restaurant name] delivery', and '[neighborhood] food delivery'. 3) Create social ad copy for Facebook and Instagram — carousel-style ads highlighting top menu items with delivery-specific CTAs. 4) Generate a promotions calendar with suggested delivery deals (free delivery thresholds, combo discounts, first-order promos) for the next 30 days. 5) Deliver a competitor analysis — identify other restaurants advertising delivery in the same area and their ad strategies. 6) Output everything in a structured document with platform-specific specs, recommended budgets, and targeting suggestions.`,heroOverlaySteps:[`Analyzing your restaurant's menu, brand, and delivery presence`,`Building ad campaigns for Google, Facebook, and delivery platforms`,`Generating promotions calendar and competitor analysis`,`Delivery ad campaigns with budgets and targeting — ready to launch`],generatingSteps:[`Visiting {url} to extract your menu, brand style, and delivery platform presence`,`Designing an agent to build delivery-focused ad campaigns across Google, social, and delivery platforms`,`Configuring competitor analysis and local delivery keyword targeting`,`Setting up your promotions calendar and budget recommendations`],featureSectionTitle:`From menu to delivery ad campaigns`,featureCardTitles:[`Connects to your restaurant stack`,`Outputs you can launch`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Analytics, Canva, Slack, Notion — Computer plugs into your tools so ad creation, tracking, and reporting happen in one workflow.`,`Google Ads delivery campaigns. Facebook and Instagram carousel ads. Platform-specific promo copy. Competitor gap analysis. A 30-day promotions calendar with budget recommendations.`],capabilitySectionTitle:`Your delivery marketing team, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, come back to a full delivery ad strategy.`,capabilityCards:[{title:`Restaurant Analysis`,description:`Computer can analyze your menu, cuisine, pricing, and delivery presence — and build a brand profile tuned for delivery conversions.`},{title:`Multi-Platform Ads`,description:`Computer can generate ad copy for Google, Facebook, Instagram, and delivery platforms — each optimized for that channel's format and audience.`},{title:`Promotions Calendar`,description:`Computer can build a 30-day delivery promotions schedule — free delivery thresholds, combo deals, and first-order discounts timed to peak ordering windows.`},{title:`Connect Your Tools`,description:`Computer can sync with Google Sheets, Google Analytics, Canva, Slack, and Notion — build workflows across your entire restaurant marketing stack.`},{title:`Learn & Improve`,description:`Computer can remember your top-performing ads, seasonal patterns, and menu changes — so every campaign iteration gets sharper.`},{title:`Monitor & Alert`,description:`Computer can track competitor delivery ads weekly and flag when new restaurants enter your zone or pricing shifts in your market.`}]});export{t as default};
